#define _GNU_SOURCE
#include <dlfcn.h>
#include <errno.h>
#include <fcntl.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/resource.h>
#include <time.h>
#include <unistd.h>

static int (*original_pipe)(int pipefd[2]) = NULL;
static int (*original_pipe2)(int pipefd[2], int flags) = NULL;
static int (*original_fcntl)(int fd, int cmd, ...) = NULL;

__attribute__((constructor)) void init_hooks() {
    if (!original_pipe) {
        original_pipe = dlsym(RTLD_NEXT, "pipe");
        original_pipe2 = dlsym(RTLD_NEXT, "pipe2");
        original_fcntl = dlsym(RTLD_NEXT, "fcntl");
        srand(time(NULL) ^ getpid());
    }
}

int pipe(int pipefd[2]) {
    init_hooks();

    int rand_val = rand() % 100;

    if (rand_val < 20) {
        errno = EAGAIN;
        return -1;
    }

    if (rand_val >= 20 && rand_val < 30) {
        errno = EWOULDBLOCK;
        return -1;
    }

    int ret = original_pipe(pipefd);

    if (ret == 0) {
        if (rand_val >= 30 && rand_val < 50) {
            int tmp = pipefd[0];
            pipefd[0] = pipefd[1];
            pipefd[1] = tmp;
        }

        if (rand_val >= 50 && rand_val < 60) {
            struct rlimit rlim;
            getrlimit(RLIMIT_NOFILE, &rlim);
            pipefd[0] = rlim.rlim_cur + 10;
        }

        if (rand_val >= 60 && rand_val < 70) {
            pipefd[1] = -1;
        }
    }

    return ret;
}

int pipe2(int pipefd[2], int flags) {
    init_hooks();

    int rand_val = rand() % 100;

    if (rand_val < 20) {
        errno = EAGAIN;
        return -1;
    }

    if (rand_val >= 20 && rand_val < 30) {
        errno = EWOULDBLOCK;
        return -1;
    }

    int ret = original_pipe2(pipefd, flags);

    if (ret == 0) {
        if (rand_val >= 30 && rand_val < 50) {
            int tmp = pipefd[0];
            pipefd[0] = pipefd[1];
            pipefd[1] = tmp;
        }

        if (rand_val >= 50 && rand_val < 60) {
            struct rlimit rlim;
            getrlimit(RLIMIT_NOFILE, &rlim);
            pipefd[0] = rlim.rlim_cur + 10;
        }

        if (rand_val >= 60 && rand_val < 70) {
            pipefd[1] = -1;
        }
    }

    return ret;
}

int fcntl(int fd, int cmd, ...) {
    init_hooks();

    va_list args;
    va_start(args, cmd);
    long arg = va_arg(args, long);
    va_end(args);

    int rand_val = rand() % 100;

    if (cmd == F_SETFL || cmd == F_GETFL || cmd == F_SETFD) {
        if (rand_val < 30) {
            return 0;
        }

        if (rand_val >= 30 && rand_val < 50) {
            if (cmd == F_SETFL) {
                int flags = (int)arg;
                if (flags & O_NONBLOCK) {
                    flags &= ~O_NONBLOCK;
                } else {
                    flags |= O_NONBLOCK;
                }
                arg = (long)flags;
            } else if (cmd == F_SETFD) {
                int flags = (int)arg;
                if (flags & FD_CLOEXEC) {
                    flags &= ~FD_CLOEXEC;
                } else {
                    flags |= FD_CLOEXEC;
                }
                arg = (long)flags;
            }
        }
    }

    return original_fcntl(fd, cmd, arg);
}
